const initialOrder = { orderNo: "", customerName: "", customerUnit: "", businessRegionSourceText:"", businessRegionCode: "", salespersonPersonId: "", serviceType: "", sourceReceivedOn: businessDateToday(), amount: "", reason: "首次录入" };

function previousBusinessMonth():string{const [year,month]=businessDateToday().slice(0,7).split("-").map(Number);return new Date(Date.UTC(year!,month!-2,1)).toISOString().slice(0,7);}

function LedgerGovernancePanel({user,orders,onChanged}:{user:User;orders:Order[];onChanged:()=>Promise<void>}){
  const isLeader=user.roles.includes("sales_assistant_leader");
  const isHr=user.roles.includes("hr");
  const[periods,setPeriods]=useState<AccountingPeriod[]>([]);
  const[corrections,setCorrections]=useState<AccountingCorrection[]>([]);
  const[reviews,setReviews]=useState<HistoricalReview[]>([]);
  const[month,setMonth]=useState(previousBusinessMonth());
  const[periodNote,setPeriodNote]=useState("");
  const[decisionNote,setDecisionNote]=useState("");
  const[message,setMessage]=useState("");
  const[busy,setBusy]=useState(false);
  const[correction,setCorrection]=useState({orderId:"",eventType:"revenue_change",occurredOn:`${previousBusinessMonth()}-01`,reason:"",businessRegionCode:"",businessRegionSourceText:"",customerUnit:"",analysisDimensionEvidence:""});
  const[review,setReview]=useState({orderId:"",lifecycleState:"active",currentRevenue:"",conclusion:"",evidence:"",reason:""});
  const[execution,setExecution]=useState<AccountingCorrection|null>(null);
  const[executionAmount,setExecutionAmount]=useState("");
  const[executionReason,setExecutionReason]=useState("");
  const load=useCallback(async()=>{
    if(!isLeader&&!isHr)return;
    const responses=await Promise.all([fetch("/api/accounting-periods"),fetch("/api/accounting-corrections"),fetch("/api/historical-order-reviews")]);
    const data=await Promise.all(responses.map((response)=>response.json()));
    const failed=responses.findIndex((response)=>!response.ok);
    if(failed>=0)throw new Error((data[failed] as {message?:string}).message??"账本治理数据加载失败");
    setPeriods((data[0] as {periods:AccountingPeriod[]}).periods??[]);
    setCorrections((data[1] as {corrections:AccountingCorrection[]}).corrections??[]);
    setReviews((data[2] as {reviews:HistoricalReview[]}).reviews??[]);
  },[isHr,isLeader]);
  useEffect(()=>{load().catch((error)=>setMessage(error instanceof Error?error.message:"账本治理数据加载失败"));},[load]);
  useEffect(()=>{if(orders[0]){setCorrection((current)=>current.orderId?current:{...current,orderId:orders[0]!.id});setReview((current)=>current.orderId?current:{...current,orderId:orders[0]!.id});}},[orders]);
  if(!isLeader&&!isHr)return null;
  async function post(url:string,payload:unknown){
    setBusy(true);setMessage("");
    try{const response=await apiFetch(url,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const data=await response.json() as {message?:string};if(!response.ok)throw new Error(data.message??"操作失败");await load();await onChanged();setMessage("操作已记录并刷新。");return true;}
    catch(error){setMessage(error instanceof Error?error.message:"操作失败");return false;}
    finally{setBusy(false);}
  }
  async function submitCorrection(event:FormEvent){event.preventDefault();const ok=await post("/api/accounting-corrections",{periodMonth:month,orderId:Number(correction.orderId),eventType:correction.eventType,occurredOn:correction.occurredOn,reason:correction.reason,businessRegionCode:correction.businessRegionCode,businessRegionSourceText:correction.businessRegionSourceText,customerUnit:correction.customerUnit,analysisDimensionEvidence:correction.analysisDimensionEvidence});if(ok)setCorrection((current)=>({...current,reason:"",analysisDimensionEvidence:""}));}
  async function submitReview(event:FormEvent){event.preventDefault();const ok=await post("/api/historical-order-reviews",{orderId:Number(review.orderId),lifecycleState:review.lifecycleState,currentRevenue:Number(review.currentRevenue),conclusion:review.conclusion,evidence:review.evidence,reason:review.reason});if(ok)setReview((current)=>({...current,currentRevenue:"",conclusion:"",evidence:"",reason:""}));}
  async function executeCorrection(event:FormEvent){event.preventDefault();if(!execution)return;const payload={type:execution.eventType,reason:executionReason,idempotencyKey:crypto.randomUUID(),correctionRequestId:Number(execution.id),...(execution.eventType==="revenue_change"?{newAmount:Number(executionAmount)}:{}),...(execution.eventType==="first_include"?{amount:Number(executionAmount)}:{})};const ok=await post(`/api/performance/orders/${execution.orderId}/events`,payload);if(ok){setExecution(null);setExecutionAmount("");setExecutionReason("");}}
  const reviewableOrders=orders.filter((order)=>order.lifecycleState==="historical_review_required");
  return <section className="governance-card" aria-labelledby="ledger-governance-title"><div className="orders-toolbar"><div><h2 id="ledger-governance-title">记账治理工作台</h2><span>关账、更正与历史核对均保留职责分离和审计</span></div><button className="icon-action" onClick={()=>load().catch((error)=>setMessage(error instanceof Error?error.message:"刷新失败"))} aria-label="刷新记账治理"><RefreshCw size={17}/></button></div>
    {message?<p className="page-message" role="status">{message}</p>:null}
    <div className="governance-grid"><form noValidate onSubmit={(event)=>event.preventDefault()}><h3>{isLeader&&isHr?"期间核对与关账":isHr?"人事关账":"组长核对确认"}</h3><label className="field"><span>记账月份</span><input type="month" value={month} onChange={(event)=>{setMonth(event.target.value);setCorrection((current)=>({...current,occurredOn:`${event.target.value}-01`}));}}/></label><Field label={isLeader&&isHr?"核对或关账说明":isHr?"关账说明":"核对说明"} value={periodNote} onChange={setPeriodNote}/>{isLeader?<button type="button" disabled={busy} onClick={()=>post(`/api/accounting-periods/${month}/confirm-close`,{note:periodNote})}>提交核对确认</button>:null}{isHr?<button type="button" disabled={busy} onClick={()=>post(`/api/accounting-periods/${month}/close`,{note:periodNote})}>关闭记账期间</button>:null}</form>
      {isLeader?<form noValidate onSubmit={submitCorrection}><h3>申请关闭月更正</h3><OrderSelect orders={orders} value={correction.orderId} onChange={(orderId)=>setCorrection((current)=>({...current,orderId}))}/><label className="field"><span>更正类型</span><select value={correction.eventType} onChange={(event)=>setCorrection((current)=>({...current,eventType:event.target.value}))}><option value="revenue_change">营业额修改</option><option value="pause">整单暂停</option><option value="restart">订单重启</option><option value="first_include">首次计入</option></select></label><Field label="原业务日期" type="date" value={correction.occurredOn} onChange={(occurredOn)=>setCorrection((current)=>({...current,occurredOn}))}/><label className="field"><span>发生时标准业务区域</span><select required value={correction.businessRegionCode} onChange={(event)=>setCorrection((current)=>({...current,businessRegionCode:event.target.value}))}><option value="">请选择</option>{standardBusinessRegions.map(([code,name])=><option key={code} value={code}>{name}</option>)}</select></label><Field label="发生时来源区域原文" value={correction.businessRegionSourceText} onChange={(businessRegionSourceText)=>setCorrection((current)=>({...current,businessRegionSourceText}))}/><Field label="发生时客户单位" value={correction.customerUnit} onChange={(customerUnit)=>setCorrection((current)=>({...current,customerUnit}))}/><Field label="分析维度证据" value={correction.analysisDimensionEvidence} onChange={(analysisDimensionEvidence)=>setCorrection((current)=>({...current,analysisDimensionEvidence}))}/><Field label="申请原因" value={correction.reason} onChange={(reason)=>setCorrection((current)=>({...current,reason}))}/><button type="submit" disabled={busy}>提交更正申请</button></form>:null}
      {isLeader?<form noValidate onSubmit={submitReview}><h3>提交历史订单核对</h3><OrderSelect orders={reviewableOrders} value={review.orderId} onChange={(orderId)=>setReview((current)=>({...current,orderId}))}/><label className="field"><span>核对后状态</span><select value={review.lifecycleState} onChange={(event)=>setReview((current)=>({...current,lifecycleState:event.target.value}))}><option value="active">正向计入</option><option value="paused">已暂停</option><option value="zero">零金额</option></select></label><Field label="核对后当前营业额" type="number" value={review.currentRevenue} onChange={(currentRevenue)=>setReview((current)=>({...current,currentRevenue}))}/><Field label="核对结论" value={review.conclusion} onChange={(conclusion)=>setReview((current)=>({...current,conclusion}))}/><Field label="核对依据" value={review.evidence} onChange={(evidence)=>setReview((current)=>({...current,evidence}))}/><Field label="核对原因" value={review.reason} onChange={(reason)=>setReview((current)=>({...current,reason}))}/><button type="submit" disabled={busy||!reviewableOrders.length}>提交人事审批</button></form>:null}</div>
    {isHr?<label className="field governance-decision"><span>审批意见</span><input value={decisionNote} onChange={(event)=>setDecisionNote(event.target.value)} placeholder="批准、驳回或撤销前填写"/></label>:null}
    <div className="governance-lists"><div><h3>记账期间</h3>{periods.length?<ul>{periods.map((period)=><li key={period.periodMonth}><strong>{period.periodMonth.slice(0,7)}</strong><span>{period.status==="closed"?`已关闭 · 版本 ${period.version}`:"开放"}{period.needsReclose?" · 待重新关账":""}</span></li>)}</ul>:<p>尚无期间治理记录。</p>}</div><div><h3>更正申请</h3>{corrections.length?<ul>{corrections.map((item)=><li key={item.id}><strong>{item.orderNo} · {eventTypeName(item.eventType)}</strong><span>{item.periodMonth.slice(0,7)} · {item.status} · 申请人 {item.requestedBy}</span><span>{item.businessRegionCode?`${businessRegionName(item.businessRegionCode)}（${item.businessRegionCode}） · ${item.businessRegionSourceText} · ${item.customerUnit} · 证据：${item.analysisDimensionEvidence}`:"缺少发生时分析维度证据，需重新提交"}</span><div className="row-actions">{isHr&&item.status==="pending"?<><button onClick={()=>post(`/api/accounting-corrections/${item.id}/approve`,{note:decisionNote})}>批准</button><button onClick={()=>post(`/api/accounting-corrections/${item.id}/reject`,{note:decisionNote})}>驳回</button></>:null}{isHr&&item.status==="approved"?<button onClick={()=>post(`/api/accounting-corrections/${item.id}/revoke`,{note:decisionNote})}>撤销</button>:null}{isLeader&&item.status==="approved"?<button onClick={()=>setExecution(item)}>执行更正</button>:null}</div></li>)}</ul>:<p>暂无更正申请。</p>}</div><div><h3>历史核对</h3>{reviews.length?<ul>{reviews.map((item)=><li key={item.id}><strong>{item.orderNo} · {item.conclusion}</strong><span>{item.status} · 核对人 {item.requestedBy} · 依据 {item.evidence}</span>{isHr&&item.status==="pending"?<div className="row-actions"><button onClick={()=>post(`/api/historical-order-reviews/${item.id}/approve`,{note:decisionNote})}>批准并解析</button><button onClick={()=>post(`/api/historical-order-reviews/${item.id}/reject`,{note:decisionNote})}>驳回</button></div>:null}</li>)}</ul>:<p>暂无历史核对记录。</p>}</div></div>
    {execution?<Modal title={`执行更正 · ${execution.orderNo}`} note={`获批范围：${execution.periodMonth.slice(0,7)} / ${eventTypeName(execution.eventType)}`} onClose={()=>setExecution(null)}><form noValidate className="business-form" onSubmit={executeCorrection}>{["revenue_change","first_include"].includes(execution.eventType)?<Field label={execution.eventType==="revenue_change"?"调整后营业额":"首次计入金额"} type="number" value={executionAmount} onChange={setExecutionAmount}/>:null}<Field label="执行原因" value={executionReason} onChange={setExecutionReason}/><div className="modal-actions"><button type="button" onClick={()=>setExecution(null)}>取消</button><button type="submit" disabled={busy}>确认追加更正事件</button></div></form></Modal>:null}
  </section>;
}

function OrderSelect({orders,value,onChange}:{orders:Order[];value:string;onChange:(value:string)=>void}){return <label className="field"><span>订单</span><select aria-label="订单" value={orders.some((order)=>order.id===value)?value:""} onChange={(event)=>onChange(event.target.value)}><option value="">请选择当前列表中的订单</option>{orders.map((order)=><option key={order.id} value={order.id}>{order.orderNo} · {order.customerName}</option>)}</select></label>;}

function CreateOrder({ onClose, onSaved }: { onClose: () => void; onSaved: () => Promise<void> }) {
  const [form, setForm] = useState(initialOrder);
  const [people, setPeople] = useState<Array<{ id:string; displayName:string }>>([]);
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  useEffect(() => { fetch("/api/performance/people").then(async (response) => {
    const data = await response.json() as { people?:Array<{ id:string; displayName:string }>; message?:string };
    if (!response.ok) throw new Error(data.message ?? "业务员列表加载失败");
    setPeople(data.people ?? []);
  }).catch((reason) => setError(reason instanceof Error ? reason.message : "业务员列表加载失败")); }, []);
  function set(name: keyof typeof form, value: string) { setForm((current) => ({ ...current, [name]: value })); }
  async function submit(event: FormEvent) {
    event.preventDefault(); setSaving(true); setError("");
    try {
      const response = await apiFetch("/api/performance/orders", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...form, salespersonPersonId: Number(form.salespersonPersonId), amount: Number(form.amount) }) });
      const data = await response.json() as { message?: string };
      if (!response.ok) throw new Error(data.message ?? "订单入账失败");
      await onSaved();
    } catch (reason) { setError(reason instanceof Error ? reason.message : "订单入账失败"); }
    finally { setSaving(false); }
  }
  return <Modal title="录入订单业绩" note="组织归属和分析维度按发生时事实固化，后续只能追加更正事件" onClose={onClose}><form noValidate className="business-form" onSubmit={submit}><div className="form-grid"><Field label="订单编号" value={form.orderNo} onChange={(v) => set("orderNo",v)}/><Field label="收到日期" value={form.sourceReceivedOn} type="date" onChange={(v) => set("sourceReceivedOn",v)}/><Field label="客户名称" value={form.customerName} onChange={(v) => set("customerName",v)}/><Field label="客户单位" value={form.customerUnit} onChange={(v) => set("customerUnit",v)}/><Field label="来源区域原文" value={form.businessRegionSourceText} onChange={(v)=>set("businessRegionSourceText",v)}/><label className="field"><span>标准业务区域</span><select required value={form.businessRegionCode} onChange={(event) => set("businessRegionCode",event.target.value)}><option value="">请选择</option>{standardBusinessRegions.map(([code,name]) => <option key={code} value={code}>{name}</option>)}</select></label><label className="field"><span>业务员</span><select required value={form.salespersonPersonId} onChange={(event) => set("salespersonPersonId",event.target.value)}><option value="">请选择</option>{people.map((person) => <option key={person.id} value={person.id}>{person.displayName}</option>)}</select></label><Field label="服务类型" value={form.serviceType} onChange={(v) => set("serviceType",v)}/><Field label="营业额" value={form.amount} type="number" onChange={(v) => set("amount",v)}/><Field label="入账原因" value={form.reason} onChange={(v) => set("reason",v)}/></div>{error ? <p className="form-error">{error}</p> : null}<div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit" disabled={saving}>{saving ? "正在入账…" : "确认入账"}</button></div></form></Modal>;
}

function AdjustOrder({ order, canEdit, onClose, onSaved }: { order: Order; canEdit: boolean; onClose: () => void; onSaved: () => Promise<void> }) {
  const [events,setEvents]=useState<PerformanceEvent[]>([]);
  const [allowed,setAllowed]=useState<string[]>([]);
  const [lifecycle,setLifecycle]=useState<OrderLifecycle>(order.lifecycleState);
  const [loading,setLoading]=useState(true);
  const [type, setType] = useState("");
  const [amount, setAmount] = useState("");
  const [reason, setReason] = useState("");
  const [error, setError] = useState("");
  const [saving,setSaving]=useState(false);
  const idempotencyKey=useRef(crypto.randomUUID());
  useEffect(()=>{
    const controller=new AbortController();
    fetch(`/api/performance/orders/${order.id}/events`,{signal:controller.signal}).then(async(response)=>{
      const data=await response.json() as {events?:PerformanceEvent[];lifecycleState?:OrderLifecycle;allowedActions?:string[];message?:string};
      if(!response.ok)throw new Error(data.message??"事件链加载失败");
      const nextAllowed=data.allowedActions??[];setEvents(data.events??[]);setLifecycle(data.lifecycleState??order.lifecycleState);setAllowed(nextAllowed);setType((current)=>nextAllowed.includes(current)?current:(nextAllowed[0]??""));
    }).catch((failure)=>{if(failure instanceof DOMException&&failure.name==="AbortError")return;setError(failure instanceof Error?failure.message:"事件链加载失败");}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});
    return()=>controller.abort();
  },[order.id,order.lifecycleState]);
  async function submit(event: FormEvent) {
    event.preventDefault();if(saving)return;setSaving(true);setError("");
    const payload = { type, reason, idempotencyKey:idempotencyKey.current, ...(type === "revenue_change" ? { newAmount: Number(amount) } : {}), ...(type === "first_include" ? { amount: Number(amount) } : {}) };
    try{
      const response = await apiFetch(`/api/performance/orders/${order.id}/events`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) });
      const data = await response.json() as { message?: string };
      if (!response.ok) { setError(data.message ?? "调整入账失败"); return; }
      await onSaved();
    }finally{setSaving(false);}
  }
  return <Modal title={order.orderNo} note={`${order.customerName} · 当前营业额 ${formatMoney(order.currentRevenue)} · 计入 ${formatMoney(order.countedAmount)}`} onClose={onClose}><section className="event-ledger" aria-labelledby="event-ledger-title"><div className="event-ledger-heading"><div><h3 id="event-ledger-title">不可变事件链</h3><p>{loading?"正在读取事件…":`${events.length} 条事件 · 按服务端账本序号排列`}</p></div><Status state={lifecycle}/></div>{!loading&&events.length?<ol>{events.map((item)=><li key={item.id}><span className="event-sequence" aria-label={`第 ${item.sequence} 条事件`}>{item.sequence}</span><div className="event-content"><div className="event-summary"><strong>{eventTypeName(item.eventType)}</strong><b className={Number(item.deltaAmount)<0?"negative":""}>{Number(item.deltaAmount)>0?"+":""}{formatMoney(item.deltaAmount)}</b>{item.resultingLifecycleState?<Status state={item.resultingLifecycleState}/>:<span className="legacy-semantic-note">原始状态未推断</span>}</div><dl><div><dt>业务日 / 记账月</dt><dd>{item.occurredOn} / {item.accountingMonth.slice(0,7)}</dd></div><div><dt>操作时间</dt><dd>{formatOperationTime(item.occurredAt)}</dd></div><div><dt>投影结果</dt><dd>营业额 {formatMoney(item.resultingCurrentRevenue)} · 计入 {formatMoney(item.resultingCountedAmount)}</dd></div><div><dt>原因 / 操作者</dt><dd>{item.reason||"—"} / {item.actorName||"历史导入"}</dd></div><div><dt>组织快照</dt><dd>{[item.departmentName,item.groupName].filter(Boolean).join(" / ")||"—"} · 组长 {item.leaderName||"—"} · 主管 {item.supervisorName||"—"}</dd></div><div><dt>分析维度快照</dt><dd>{item.businessRegionCode?`${businessRegionName(item.businessRegionCode)} (${item.businessRegionCode}) · 来源 ${item.businessRegionSourceText} · 客户单位 ${item.customerUnit}`:"待补齐（无受控来源证据）"}</dd></div></dl></div></li>)}</ol>:!loading&&!error?<p className="event-empty">没有可显示的事件。</p>:null}</section>{error ? <p className="form-error event-error" role="alert">{error}</p> : null}{!loading&&canEdit && allowed.length ? <form noValidate className="business-form event-form" onSubmit={submit}><div className="event-options">{allowed.includes("revenue_change") ? <button type="button" className={type==="revenue_change"?"selected":""} onClick={() => setType("revenue_change")}><RefreshCw size={17}/>修改营业额</button> : null}{allowed.includes("pause") ? <button type="button" className={type==="pause"?"selected":""} onClick={() => setType("pause")}><PauseCircle size={17}/>整单暂停</button> : null}{allowed.includes("restart") ? <button type="button" className={type==="restart"?"selected":""} onClick={() => setType("restart")}><PlayCircle size={17}/>订单重启</button> : null}{allowed.includes("first_include") ? <button type="button" className={type==="first_include"?"selected":""} onClick={() => setType("first_include")}><Plus size={17}/>首次计入</button> : null}</div><p className="form-note">操作时间和记账月由服务器确定，组织快照按该业务日的有效任职自动解析。</p><div className="form-grid">{type === "revenue_change" || type === "first_include" ? <Field label={type === "revenue_change" ? "调整后营业额" : "首次计入金额"} value={amount} type="number" onChange={setAmount}/> : null}<Field label="原因（必填）" value={reason} onChange={setReason}/></div><div className="modal-actions"><button type="button" onClick={onClose}>取消</button><button type="submit" disabled={saving} aria-busy={saving}>{saving?"正在追加…":"确认追加事件"}</button></div></form> : !loading?<div className="permission-note">{lifecycle==="historical_review_required"?"该历史订单需要先完成核对与人事批准，当前不能追加事件。":"当前订单状态没有可执行操作，或当前角色仅可查看。"}</div>:null}</Modal>;
}

function Field({ label, value, onChange, type="text" }: { label: string; value: string; onChange: (value: string) => void; type?: string }) { return <label className="field"><span>{label}</span><input required value={value} type={type} min={type === "number" ? "0" : undefined} step={type === "number" ? "0.01" : undefined} onChange={(event) => onChange(event.target.value)}/></label>; }
function Modal({ title, note, onClose, children }: { title: string; note: string; onClose: () => void; children: ReactNode }) { const titleId=useId();const noteId=useId();const dialogRef=useRef<HTMLElement>(null);const closeRef=useRef(onClose);closeRef.current=onClose;useEffect(()=>{const prior=document.activeElement instanceof HTMLElement?document.activeElement:null;const root=document.getElementById("root");const priorOverflow=document.body.style.overflow;root?.setAttribute("inert","");root?.setAttribute("aria-hidden","true");document.body.style.overflow="hidden";const dialog=dialogRef.current;dialog?.focus();function keydown(event:KeyboardEvent){if(event.key==="Escape"){event.preventDefault();closeRef.current();return;}if(event.key!=="Tab"||!dialog)return;const controls=[...dialog.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[href],[tabindex]:not([tabindex="-1"])')].filter((item)=>!item.hasAttribute("hidden"));if(!controls.length){event.preventDefault();dialog.focus();return;}const first=controls[0]!;const last=controls.at(-1)!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}document.addEventListener("keydown",keydown);return()=>{document.removeEventListener("keydown",keydown);root?.removeAttribute("inert");root?.removeAttribute("aria-hidden");document.body.style.overflow=priorOverflow;prior?.focus();};},[]);return createPortal(<div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section ref={dialogRef} tabIndex={-1} className="modal" role="dialog" aria-modal="true" aria-labelledby={titleId} aria-describedby={noteId}><header><div><h2 id={titleId}>{title}</h2><p id={noteId}>{note}</p></div><button onClick={onClose} aria-label="关闭">×</button></header>{children}</section></div>,document.body); }
function Status({ state }: { state: OrderLifecycle }) { const names:Record<OrderLifecycle,string> = { draft:"草稿", active:"正向计入", paused:"已暂停", zero:"零金额",historical_review_required:"待历史核对" }; return <span className={`status status-${state}`}>{names[state]}</span>; }
function achievementReasonText(value:PersonalAchievement["calculationReason"],scope:string){return value===null?null:({PERIOD_IN_FUTURE:"未来月份不计算目标达成",TARGET_NOT_ACTIVE:`${scope}目标尚未生效`,TARGET_AMOUNT_NOT_POSITIVE:"生效目标金额必须大于零",TARGET_SCOPE_AMBIGUOUS:"存在多个生效的销售组织目标，暂不计算"} as const)[value];}
function OrganizationAchievementCard({scope,title,countNote,achievement,onOpen}:{scope:"部门"|"销售组织";title:string;countNote:string;achievement:PersonalAchievement;onOpen:(metric:"actual"|"gap")=>void}){const reason=achievementReasonText(achievement.calculationReason,scope);return <article className="team-achievement orders-card" aria-label={title}><PanelTitle title={title} note={countNote}/><section className="metric-band personal-metrics"><Metric label={`${scope}生效目标`} value={achievement.targetAmount===null?"—":formatMoney(achievement.targetAmount)} note={reason??`当前月${scope}目标`}/><Metric label={`${scope}业绩`} value={formatMoney(achievement.actualAmount)} note={`${achievement.eventCount} 条事件`} onClick={()=>onOpen("actual")} actionLabel={`查看${scope}业绩构成`}/><Metric label={`${scope}差距`} value={achievement.gapAmount===null?"不计算":formatMoney(achievement.gapAmount)} note={reason??`生效目标减${scope}业绩`} onClick={achievement.gapAmount===null?undefined:()=>onOpen("gap")} actionLabel={achievement.gapAmount===null?undefined:`查看${scope}差距构成`}/><Metric label={`${scope}达成率`} value={achievement.achievementRate===null?"不计算":`${achievement.achievementRate}%`} note={reason??`${scope}业绩 ÷ 生效目标`}/><Metric label="自然日进度" value={achievement.timeProgressRate===null?"不计算":`${achievement.timeProgressRate}%`} note={reason??"按上海自然日计算"}/><Metric label="进度偏差" value={achievement.progressVariance===null?"不计算":`${achievement.progressVariance}%`} note={reason??"达成率减自然日进度"} warning={achievement.progressVariance!==null&&Number(achievement.progressVariance)<0}/></section></article>}
function OrganizationHierarchy({departments}:{departments:DepartmentAchievementDrilldown[]}){
  return <div className="group-drilldown">{departments.map((department)=>{
    const departmentReason=achievementReasonText(department.calculationReason,"部门");
    return <section className="orders-card group-member" aria-label={`${department.departmentName}部门构成`} key={department.departmentKey}>
      <PanelTitle title={department.departmentName} note={`${department.groupCount} 个小组 · ${department.eventCount} 条事件 · 实际 ${formatMoney(department.actualAmount)} · ${departmentReason??`达成率 ${department.achievementRate}%`}`}/>
      {department.groups.map((group)=>{
        const groupReason=achievementReasonText(group.calculationReason,"小组");
        return <article className="orders-card group-member" aria-label={`${group.groupName}小组构成`} key={group.groupKey}>
          <PanelTitle title={group.groupName} note={`${group.memberCount} 位事件责任人 · ${group.eventCount} 条事件 · 实际 ${formatMoney(group.actualAmount)} · ${groupReason??`达成率 ${group.achievementRate}%`}`}/>
          <AchievementMembers members={group.members}/>
          {group.members.length===0?<p className="empty-cell">当前月份没有小组业绩事件。</p>:null}
        </article>;
      })}
      {department.groups.length===0?<p className="empty-cell">当前月份没有部门小组。</p>:null}
    </section>;
  })}</div>;
}
function AchievementMembers({members}:{members:GroupAchievementMember[]}){
  return <>{members.map((member)=><section className="orders-card group-member" key={member.personKey}>
    <PanelTitle title={member.name} note={`${member.orders.length} 笔订单 · ${member.eventCount} 条事件 · 净额 ${formatMoney(member.actualAmount)}`}/>
    {member.orders.map((order)=><div className="group-order" key={order.orderId}>
      <h4>{order.orderNo} · {order.customerName}<small>{order.eventCount} 条事件 · 净额 {formatMoney(order.actualAmount)}</small></h4>
      <div className="orders-table-wrap"><table><thead><tr><th>不可变事件</th><th>业务日 / 记账月</th><th>金额方向</th><th>状态 / 计入</th><th>组织归属</th><th>分析维度</th><th>原因</th></tr></thead><tbody>{order.events.map((event)=><tr key={event.id}><td>{eventTypeName(event.eventType)} · 第 {event.sequence} 条</td><td>{event.occurredOn} / {event.accountingMonth}</td><td className={event.deltaAmount.startsWith("-")?"negative":""}>{event.deltaAmount.startsWith("-")?"负向":"正向"} {formatMoney(event.deltaAmount.startsWith("-")?event.deltaAmount.slice(1):event.deltaAmount)}</td><td>{event.resultingLifecycleState?<><Status state={event.resultingLifecycleState}/><small className="table-secondary">计入至 {formatMoney(event.resultingCountedAmount)}</small></>:"原始状态未推断"}</td><td>{[event.departmentName,event.groupName].filter(Boolean).join(" / ")||"—"}</td><td>待补齐</td><td>{event.reason??"—"}</td></tr>)}</tbody></table></div>
    </div>)}
  </section>)}</>;
}
function formatMoney(value: string | number) {
  if(typeof value==="string"){
    const decimal=/^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(value);
    if(decimal)return `${decimal[1]}¥${new Intl.NumberFormat("zh-CN").format(BigInt(decimal[2]!))}.${(decimal[3]??"").padEnd(2,"0")}`;
  }
  return new Intl.NumberFormat("zh-CN", { style: "currency", currency: "CNY", minimumFractionDigits: 2 }).format(Number(value));
}
function formatOperationTime(value:string){return new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false}).format(new Date(value));}
function eventTypeName(type: string) { return ({ initial:"首次录入", revenue_change:"营业额修改", pause:"整单暂停", restart:"订单重启", first_include:"首次计入", legacy_adjustment:"历史迁移",historical_review_resolution:"历史核对解析" } as Record<string,string>)[type] ?? type; }
function businessRegionName(code:string){return standardBusinessRegions.find(([value])=>value===code)?.[1]??code;}
function goalLevelName(level: string) { return ({ sales_manager:"销售经理总目标", department:"部门目标", group:"小组目标", personal:"个人目标" } as Record<string,string>)[level] ?? level; }
function goalStatusName(status: string) { return ({ draft:"草稿", pending_signature:"待责任人确认", pending_gm:"待总经理审批", pending_hr:"待人事审批", active:"已生效", rejected:"已拒绝", superseded:"已替代" } as Record<string,string>)[status] ?? status; }
function workflowStatusName(status:string){return ({pending:"待处理",accepted:"已接受，待重新确认",rejected:"已拒绝",withdrawn:"已撤回",invalidated:"已失效",completed:"已完成"} as Record<string,string>)[status]??status;}
function goalAuditName(action:string){return ({"goal.version_created":"创建目标版本","goal.version_confirmed":"责任人实名确认","goal.version_signed":"历史责任人确认","goal.approved":"审批批准","goal.rejected":"审批拒绝","goal.version_superseded":"替代旧版本","goal.change_requested":"提交修改申请","goal.change_accepted":"接受修改申请","goal.change_rejected":"拒绝修改申请","goal.change_withdrawn":"撤回修改申请","goal.change_invalidated":"修改申请失效","goal.change_completed":"修改流程完成","goal.linkage_requested":"生成目标联动待办","goal.linkage_decided":"完成目标联动选择"} as Record<string,string>)[action]??action;}

function PanelTitle({ title, note }: { title: string; note: string }) { return <div className="panel-title"><div><h2>{title}</h2><p>{note}</p></div></div>; }
function Metric({label,value,note,warning,negative,onClick,actionLabel}:{label:string;value:string;note:string;warning?:boolean;negative?:boolean;onClick?:(()=>void)|undefined;actionLabel?:string|undefined}) { return <div className="metric"><span>{label}</span>{onClick?<button type="button" className={`metric-value-action${negative?" negative":""}`} aria-label={actionLabel} onClick={onClick}>{value}</button>:<strong className={negative?"negative":""}>{value}</strong>}<small className={warning?"warning":""}>{note}</small></div>; }
function TrendChart({year,monthly}:{year:string;monthly:Array<{month:string;total:string}>}) { const totals=new Map(monthly.map((item)=>[item.month,Number(item.total)]));const filled=Array.from({length:12},(_,index)=>totals.get(`${year}-${String(index+1).padStart(2,"0")}`)??0);const max=Math.max(1,...filled);const x=(index:number)=>44+index*(526/11);const points=filled.map((value,index)=>`${x(index)},${190-(value/max)*150}`).join(" ");return <div className="chart"><svg viewBox="0 0 590 220" role="img" aria-label={`${year}年1月至12月业绩折线图`}><g className="grid-lines">{[40,90,140,190].map((y)=><line key={y} x1="42" y1={y} x2="570" y2={y}/>)}</g><polyline points={points} fill="none" stroke="#2f6fed" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/>{filled.map((value,index)=><circle key={index} cx={x(index)} cy={190-(value/max)*150} r="5" fill="#fff" stroke="#2f6fed" strokeWidth="3"/>)}</svg><div className="chart-labels">{Array.from({length:12},(_,index)=><span key={index}>{index+1}月</span>)}</div></div>; }
